css_extra:
/* ---- teclas (kbd) ---- */
.tc { display:inline-flex; align-items:center; justify-content:center; gap:6px; min-width:2.3em; height:2.1em; padding:0 .6em;
  font-family:var(--fonte-tit); font-weight:700; font-size:.95em; line-height:1; color:var(--p); background:#fff;
  border:1px solid var(--linha-bt); border-bottom:5px solid var(--linha-bt); border-radius:9px; white-space:nowrap; vertical-align:middle }
.tc.lg { padding:0 .8em }
.tc.espaco { width:7.5em }
.tc .win { width:1.05em; height:1.05em; fill:#0078D4 }
.tecla-cab { display:flex; align-items:center; gap:14px; margin-bottom:10px }
.tecla-cab h3 { margin:0 !important }
.card .tecla-cab .tc { font-size:1.05em; height:2.3em }
.setas { display:inline-grid; grid-template-columns:repeat(3,auto); gap:3px }
.setas .tc { min-width:1.9em; height:1.7em; padding:0; font-size:.85em }
.setas .s-up { grid-column:2; grid-row:1 }
.setas .tc:not(.s-up) { grid-row:2 }
.combo { display:inline-flex; align-items:center; gap:6px; flex-wrap:nowrap }
.combo i { font-style:normal; font-weight:800; color:var(--c) }
.combo .tc { font-size:.85em; height:1.95em }
.fileira { display:flex; gap:8px; margin-top:auto; padding-top:14px }
.card.az .fileira .tc { color:var(--az); border-color:var(--destaque); border-bottom-color:var(--destaque) }
.g .card .txt-bloco p { font-size:var(--fs-corpo) }
.card .txt-bloco { line-height:1.45 }
/* ---- slide 5: legenda dos tipos ---- */
.legenda-tipos { display:grid; grid-template-columns:repeat(5,1fr); gap:10px }
.legenda-tipos .lt { border-radius:12px; padding:9px 12px; border:1px solid; line-height:1.3 }
.legenda-tipos .lt b { display:block; font-family:var(--fonte-tit); font-size:15px; margin-bottom:3px }
.legenda-tipos .lt span { font-size:var(--fs-min) }
.lt-alfa { background:#EAF3EE; border-color:#9CC7AE !important; color:#1C5A3E }
.lt-func { background:#FBEFEC; border-color:#E2AFA5 !important; color:#7E3A30 }
.lt-esp  { background:#E3E9E5; border-color:#9AAEA3 !important; color:#24513C }
.lt-nav  { background:#F8F0DC; border-color:#DDBF7A !important; color:#7A5A12 }
.lt-num  { background:#E6EFF5; border-color:#9DBBD0 !important; color:#2D5872 }
#s5 .fig, #s6 .fig { border:0; padding:0 }
/* ---- slide 8: ícones ---- */
.icone { width:52px; height:52px; border-radius:50%; background:#fff; border:1px solid var(--vd-bd); display:flex; align-items:center; justify-content:center; margin-bottom:12px; color:var(--ve) }
.icone svg { width:28px; height:28px; fill:currentColor }
#s8 .card h3 { font-size:1.15em; margin:0 0 6px !important; color:var(--vd-tx) }
/* ---- slide 9: indicador ---- */
#s9 .kpi b { font-size:2.1em }
#s9 .kpi > div:last-child b { font-size:1.6em }
/* ---- passos (11–13) ---- */
#s11 .col:last-child, #s12 .col:first-child, #s13 .col:last-child { justify-content:center }
#s11 .chips, #s12 .chips, #s13 .chips { align-self:flex-start }
#s11 .tit-bloco, #s12 .tit-bloco, #s13 .tit-bloco { font-size:1.3em; margin:2px 0 0 }
#s10 .fig img { max-height:240px }
#s3 .card, #s4 .card { flex:1 1 0; justify-content:center; padding:16px 20px }
#s3 .card .txt-bloco, #s4 .card .txt-bloco { font-size:1.05em }
#s8 .card { justify-content:center; padding:20px 20px }
#s8 .icone { width:72px; height:72px; margin-bottom:16px }
#s8 .icone svg { width:38px; height:38px }
#s8 .card h3 { font-size:1.35em }
#s8 .card .txt-bloco { font-size:1.08em }
#s9 .kpi b { font-size:3.2em }
#s9 .kpi span { font-size:17px }
#s7 .tb2 { table-layout:fixed }
#s7 .tb2 th, #s7 .tb2 td { text-align:left; vertical-align:middle }
#s7 .tb2 th:first-child, #s7 .tb2 td:first-child { width:46% }
#s7 .combo .tc { font-size:1em }
